import {TODAY,fmt,short,escape as e,id,seed,load,persist,monthRows,totals,balance,breakdown,money,validateTxn,parseQuick} from './model.js';

const paths={wallet:'M20 8V5a2 2 0 0 0-2-2H5a3 3 0 0 0 0 6h15v12H5a3 3 0 0 1-3-3V6 M20 12h-5v5h5 M16 14.5h.1',home:'m3 10 9-7 9 7v10H3Z M9 20v-7h6v7',list:'M8 5h13M8 12h13M8 19h13M3 5h.1M3 12h.1M3 19h.1',chart:'M4 19V9M10 19V4M16 19v-7M22 19H2',plan:'M8 3h8v4H8Z M8 5H5v16h14V5h-3 M8 12h8M8 16h5',plus:'M12 5v14M5 12h14',chevron:'m9 5 7 7-7 7',left:'m15 5-7 7 7 7',down:'m6 9 6 6 6-6',x:'m6 6 12 12M18 6 6 18',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',in:'M7 5v14h12M7 19 19 7',out:'M7 19V5h12M7 5l12 12',spark:'m12 2 2.8 7.2L22 12l-7.2 2.8L12 22l-2.8-7.2L2 12l7.2-2.8Z',mic:'M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0Z M5 10v2a7 7 0 0 0 14 0v-2 M12 19v3M8 22h8',image:'M3 3h18v18H3Z m3 14 4-4 4 5 3-3 4 5M8 7h.1',camera:'M8 5 9 3h6l1 2h5v15H3V5Z M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8',send:'m3 3 19 9-19 9 4-9-4-9 M7 12h15',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',edit:'m16 3 5 5-12 12-6 1 1-6Z M13 6l5 5',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7',check:'m4 12 5 5L20 6',tag:'M3 3h8l10 10-8 8L3 11Z M7 7h.1',transfer:'M3 7h18l-4-4M21 17H3l4 4',arrow:'M4 12h16m-6-6 6 6-6 6',info:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20 M12 11v6M12 7h.1',reset:'M3 11a9 9 0 1 1 2 7 M3 3v8h8',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',target:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20 M12 6a6 6 0 1 0 0 12 6 6 0 0 0 0-12 M12 10a2 2 0 1 0 0 4 2 2 0 0 0 0-4',stop:'M6 6h12v12H6Z'};
paths.paperclip='m21 11-9 9a6 6 0 0 1-8.5-8.5l10-10a4 4 0 0 1 5.7 5.7L9 17.5a2 2 0 0 1-2.8-2.8L15 6';
paths.imagePlus='M16 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V8 M16 5h6M19 2v6 M8 8h.1 m-5 9 5-5 4 4 3-3 6 6';
paths.company='M3 21V7h10v14M13 11h8v10M7 11h2M7 15h2M17 15h1M7 19h2M17 19h1M1 21h22';
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.wallet}"></path></svg>`;
const app=document.getElementById('app'),sheet=document.getElementById('sheet');
let state=load(),screen='home',month='2026-10',hideBalance=false,storageOk=true,planTab='budgets',reportType='expense';
let filters={type:'all',wallet:'all',category:'all',search:''};
let sendDestination='personal',editingCategoryId=null;
let entry=null,categoryContext=null,categoryType='expense',newEmoji='🏷️',toastTimer;
const cat=cid=>state.categories.find(c=>c.id===cid)??{name:'Chưa phân loại',emoji:'❔',color:'#b4bcad'};
const wallet=wid=>state.wallets.find(w=>w.id===wid)??{name:'Ví',emoji:'👛'};
const monthText=()=>`Tháng ${Number(month.slice(5))}, ${month.slice(0,4)}`;
const sumBalance=()=>state.wallets.reduce((s,w)=>s+balance(state,w.id),0);
const labelType=type=>type==='income'?'Thu':type==='expense'?'Chi':'Chuyển ví';
const progress=(value,max)=>Math.max(0,Math.min(100,Math.round(value/max*100)));
const dateLabel=date=>date===TODAY?'Hôm nay · 04/10':date==='2026-10-03'?'Hôm qua · 03/10':date.split('-').reverse().join('/');
function toast(message){const node=document.getElementById('toast');node.textContent=message;node.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('show'),3500);}
function commit(message){storageOk=persist(state);render();if(message)toast(message+(storageOk?'':' · Chỉ lưu tạm trong phiên này'));}
function close(){sheet.close();if(entry?.image)URL.revokeObjectURL(entry.image);entry=null;categoryContext=null;}
sheet.addEventListener('cancel',event=>{event.preventDefault();close();});
sheet.addEventListener('click',event=>{if(event.target===sheet){const r=sheet.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)close();}});
function modal(title,body,footer=''){sheet.innerHTML=`<div class="sheet-handle"></div><header class="sheet-header"><h2 id="sheet-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="Đóng">${icon('x')}</button></header><div class="sheet-body">${body}</div>${footer?`<footer class="sheet-footer">${footer}</footer>`:''}`;if(!sheet.open)sheet.showModal();sheet.scrollTop=0;}
const button=(action,text,style='primary',extra='')=>`<button class="btn ${style}" data-action="${action}" ${extra}>${text}</button>`;
const empty=(title,detail,action='entry',text='Ghi khoản đầu tiên')=>`<div class="empty"><div class="empty-emoji">🌱</div><h3>${title}</h3><p>${detail}</p>${action?button(action,text,'soft'):''}</div>`;
const navItems=[['home','home','Tổng quan'],['transactions','list','Giao dịch'],['plans','plan','Ngân sách'],['reports','chart','Báo cáo']];
function monthPicker(compact=false){return `<div class="month-picker ${compact?'compact-month':''}"><button class="icon-btn" data-action="month-prev" aria-label="Tháng trước">${icon('left')}</button><span aria-label="${monthText()}">${compact?`${Number(month.slice(5))}.${month.slice(0,4)}`:monthText()}</span><button class="icon-btn" data-action="month-next" aria-label="Tháng sau">${icon('chevron')}</button></div>`;}
function render(){
 const nav=navItems.map(([key,i,label])=>`<button data-action="nav" data-screen="${key}" class="${screen===key?'active':''}" ${screen===key?'aria-current="page"':''}>${icon(i)}${label}</button>`);
 app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">${icon('wallet')}</span><div>Ví của tôi<small>BY iHOMECRM</small></div></div><nav class="side-nav" aria-label="Điều hướng chính">${nav.join('')}<button data-action="categories">${icon('tag')}Danh mục</button><button data-action="wallets">${icon('wallet')}Ví & tài khoản</button></nav><div style="margin-top:24px">${button('entry',icon('plus')+' Ghi thu chi','primary wide')}</div><div class="side-bottom"><p style="margin:12px 0">Một góc riêng cho<br>tài chính của bạn.</p><a href="./flow.html">${icon('plan')} Sơ đồ & thiết kế ${icon('arrow')}</a></div></aside><div class="workspace">${!storageOk?'<p class="storage-warning">Trình duyệt không cho lưu dữ liệu. Các thay đổi chỉ giữ trong phiên hiện tại.</p>':''}<main class="screen-entrance" id="main">${screen==='home'?home():screen==='transactions'?transactions():screen==='plans'?plans():reports()}</main></div><nav class="bottom-nav" aria-label="Điều hướng trên điện thoại">${nav.slice(0,2).join('')}<button class="add-nav" data-action="entry" aria-label="Ghi thu chi">${icon('plus')}</button>${nav.slice(2).join('')}</nav></div>`;
}
function txnRow(t){const c=cat(t.category),isTransfer=t.type==='transfer';return `<button class="txn" data-action="edit-txn" data-id="${e(t.id)}" aria-label="Xem ${e(t.note||c.name)}"><span class="category-icon">${isTransfer?'↔️':c.emoji}</span><span class="grow"><span class="txn-title" style="display:block">${e(t.note||c.name)}</span><span class="txn-sub">${isTransfer?`${e(wallet(t.wallet).name)} → ${e(wallet(t.toWallet).name)}`:`${e(c.name)} · ${e(wallet(t.wallet).name)}`}</span></span><span><span class="txn-money ${t.type==='income'?'positive':''}" style="display:block">${isTransfer?'':t.type==='income'?'+':'−'}${fmt(t.amount)}</span><span class="txn-tag" style="display:block;text-align:right">${labelType(t.type)}</span></span></button>`;}
function grouped(rows){const dates=[...new Set(rows.map(t=>t.date))].sort().reverse();return dates.map(date=>`<div class="date-group">${dateLabel(date)}</div>${rows.filter(t=>t.date===date).map(txnRow).join('')}`).join('');}
function budgetItem(b,edit=false){const c=cat(b.category),spent=monthRows(state,month).filter(t=>t.type==='expense'&&t.category===b.category).reduce((s,t)=>s+t.amount,0),pct=progress(spent,b.amount);return `<div class="budget-item"><div class="between"><div class="row" style="gap:9px"><span style="font-size:20px">${c.emoji}</span><span class="budget-label">${e(c.name)}</span></div>${edit?`<button class="icon-btn" data-action="edit-budget" data-id="${b.id}" aria-label="Sửa ngân sách ${e(c.name)}">${icon('edit')}</button>`:`<span class="budget-amount">${short(spent)} <span class="muted">/ ${short(b.amount)}</span></span>`}</div>${edit?`<div class="between small" style="margin-top:7px"><span>${fmt(spent)}</span><span class="muted">/ ${fmt(b.amount)}</span></div>`:''}<div class="progress ${spent>b.amount?'over':pct>=80?'warn':''}"><span style="width:${pct}%"></span></div><div class="budget-note">${spent>b.amount?'Vượt '+fmt(spent-b.amount):'Còn '+fmt(b.amount-spent)} · ${Math.round(spent/b.amount*100)}% đã dùng</div></div>`;}
function home(){const total=totals(monthRows(state,month)),remaining=state.monthlyLimit-total.expense,rows=monthRows(state,month).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);return `<div class="dashboard-grid"><section class="card balance-card"><div class="balance-header"><span class="balance-label">Tổng số dư các ví</span><div class="balance-tools">${monthPicker(true)}<button class="icon-btn" data-action="hide-balance" aria-label="${hideBalance?'Hiện':'Ẩn'} số dư">${icon('eye')}</button></div></div><div class="balance-number money" data-testid="total-balance">${hideBalance?'••• ••• •••':fmt(sumBalance())}</div><span class="balance-sub">Số dư hiện tại · ${state.wallets.length} ví cá nhân</span><div class="stat-row"><div><div class="stat-label">${icon('in')} Thu trong tháng</div><div class="stat-value money">${fmt(total.income)}</div></div><div><div class="stat-label">${icon('out')} Chi trong tháng</div><div class="stat-value money" data-testid="month-expense">${fmt(total.expense)}</div></div></div></section><section class="card quick-card">${quickLauncher()}</section></div><div class="wallet-strip">${state.wallets.filter(w=>!w.hidden).map(w=>`<button class="wallet-mini" data-action="filter-wallet" data-id="${w.id}"><span class="name"><span class="emoji">${w.emoji}</span>${e(w.name)}</span><strong class="money">${hideBalance?'••• •••':fmt(balance(state,w.id))}</strong></button>`).join('')}<button class="wallet-manage" data-action="wallets" aria-label="Quản lý ví">${icon('settings')}<span>Quản lý ví</span></button></div><div class="dashboard-grid" style="margin-top:20px"><section class="card recent-card"><div class="section-heading between"><h2>Giao dịch gần đây</h2><button class="link-btn" data-action="nav" data-screen="transactions">Xem tất cả ${icon('chevron')}</button></div>${rows.length?grouped(rows):empty('Tháng này còn trống','Ghi lại khoản đầu tiên của bạn.')}</section><section class="card budget-card"><div class="section-heading between"><h2>Trong tầm tay</h2><button class="link-btn" data-action="nav" data-screen="plans">Ngân sách ${icon('chevron')}</button></div><div class="budget-total"><div class="between"><span class="small muted">${remaining<0?'Vượt ngân sách tháng':'Còn có thể chi'}</span><strong class="money ${remaining<0?'negative':''}">${fmt(Math.abs(remaining))}</strong></div><div class="progress ${remaining<0?'over':''}"><span style="width:${progress(total.expense,state.monthlyLimit)}%"></span></div><p>Đã chi ${short(total.expense)} / ngân sách ${short(state.monthlyLimit)}</p></div>${state.budgets.slice(0,3).map(b=>budgetItem(b)).join('')}<div class="advice">${icon('info')}<span>${state.budgets.some(b=>monthRows(state,month).filter(t=>t.type==='expense'&&t.category===b.category).reduce((s,t)=>s+t.amount,0)>=b.amount*.8)?'Có danh mục đã dùng hơn 80% ngân sách. Xem Ngân sách để điều chỉnh.':'Ngân sách còn trong giới hạn bạn đặt. Mỗi khoản ghi lại giúp bạn nhìn rõ hơn.'}</span></div></section></div>`;}
function filtered(){return monthRows(state,month).filter(t=>(filters.type==='all'||t.type===filters.type)&&(filters.wallet==='all'||t.wallet===filters.wallet||t.toWallet===filters.wallet)&&(filters.category==='all'||t.category===filters.category)&&`${t.note} ${cat(t.category).name} ${t.amount}`.toLocaleLowerCase('vi').includes(filters.search.toLocaleLowerCase('vi'))).sort((a,b)=>b.date.localeCompare(a.date));}
function transactions(){return `<div class="stack"><div class="transaction-tools"><div class="search"><input type="search" id="txn-search" placeholder="Tìm giao dịch…" aria-label="Tìm giao dịch" value="${e(filters.search)}"></div>${monthPicker(true)}</div><div class="between" style="flex-wrap:wrap"><div class="chip-row">${[['all','Tất cả'],['expense','Chi tiêu'],['income','Thu nhập'],['transfer','Chuyển ví']].map(([value,label])=>`<button class="chip ${filters.type===value?'active':''}" data-action="filter-type" data-value="${value}">${label}</button>`).join('')}</div><button class="link-btn" data-action="transaction-filters">${icon('wallet')} ${filters.wallet==='all'?'Mọi ví':e(wallet(filters.wallet).name)} ${icon('down')}</button></div>${filters.category!=='all'?`<div>${button('clear-category',e(cat(filters.category).name)+' '+icon('x'),'soft')}</div>`:''}<section class="card" id="txn-list">${transactionList()}</section><button class="btn soft wide" data-action="transfer">${icon('transfer')} Chuyển tiền giữa ví</button></div>`;}
function transactionList(){const rows=filtered(),t=totals(rows);return `<div class="between small muted" style="margin-bottom:9px"><span>${rows.length} giao dịch</span><span>Thu ${short(t.income)} · Chi ${short(t.expense)}</span></div>${rows.length?grouped(rows):empty('Chưa có giao dịch phù hợp','Thử tháng khác hoặc thay đổi bộ lọc.','clear-filters','Xóa bộ lọc')}`;}
function plans(){const t=totals(monthRows(state,month));return `<div class="tabs" style="margin-bottom:20px"><button class="${planTab==='budgets'?'active':''}" data-action="plan-tab" data-value="budgets">Ngân sách</button><button class="${planTab==='goals'?'active':''}" data-action="plan-tab" data-value="goals">Mục tiêu tiết kiệm</button></div>${planTab==='budgets'?`<div class="stack"><section class="card"><div class="between compact-card-header"><div><h2>Ngân sách</h2><p class="hint">Tất cả ví cá nhân</p></div>${monthPicker(true)}</div><div class="between budget-amount-row"><div class="balance-number money" style="font-size:29px;margin:15px 0">${fmt(state.monthlyLimit)}</div><button class="icon-btn" data-action="monthly-budget" aria-label="Sửa ngân sách tháng">${icon('edit')}</button></div><div class="progress ${t.expense>state.monthlyLimit?'over':''}"><span style="width:${progress(t.expense,state.monthlyLimit)}%"></span></div><p class="hint" style="margin-top:12px">Đã chi ${fmt(t.expense)} · ${t.expense>state.monthlyLimit?'Vượt':'Còn'} ${fmt(Math.abs(state.monthlyLimit-t.expense))}</p></section><section class="card"><div class="between"><h2>Theo danh mục</h2><div class="row compact-actions"><button class="icon-btn" data-action="categories" aria-label="Quản lý danh mục" title="Quản lý danh mục">${icon('tag')}</button><button class="link-btn" data-action="new-budget">${icon('plus')} Thêm</button></div></div><p class="hint" style="margin-top:10px">Hạn mức riêng cho từng danh mục, tính chi tiêu từ tất cả ví cá nhân.</p>${state.budgets.map(b=>budgetItem(b,true)).join('')||empty('Chưa có ngân sách','Đặt giới hạn cho danh mục bạn quan tâm.','new-budget','Tạo ngân sách')}<p class="hint" style="margin-top:20px">Các hạn mức lặp lại hằng tháng. Chuyển ví và khoản công ty không tính vào ngân sách cá nhân.</p></section></div>`:`<div class="stack">${state.goals.map(g=>`<section class="card goal-card"><div class="row"><span class="goal-icon">${g.emoji}</span><div><h2>${e(g.name)}</h2><p class="hint">${Math.round(g.saved/g.target*100)}% hành trình của bạn</p></div></div><div class="progress"><span style="width:${progress(g.saved,g.target)}%"></span></div><div class="between small"><strong>${fmt(g.saved)}</strong><span class="muted">/ ${fmt(g.target)}</span></div><button class="btn soft wide" data-action="contribute" data-id="${g.id}">${icon('plus')} Bỏ thêm vào quỹ</button><p class="hint" style="margin-top:9px">Chuyển vào Ví tiết kiệm, không tính là khoản chi.</p></section>`).join('')}<button class="btn wide" data-action="new-goal">${icon('plus')} Tạo mục tiêu mới</button></div>`}`;}
function reports(){const rows=monthRows(state,month),t=totals(rows),groups=breakdown(state,month,reportType),total=reportType==='expense'?t.expense:t.income;let cursor=0;const gradient=groups.map(g=>{const start=cursor;cursor+=g.amount/total*100;return `${cat(g.category).color} ${start}% ${cursor}%`;}).join(',');const six=Array.from({length:6},(_,i)=>{const d=new Date(`${month}-15T12:00:00Z`);d.setUTCMonth(d.getUTCMonth()-5+i);const m=d.toISOString().slice(0,7);return {month:m,...totals(monthRows(state,m))};}),max=Math.max(...six.flatMap(t=>[t.income,t.expense]),1);return `<div class="report-summary"><div class="report-stat"><p>Thu nhập trong tháng</p><strong class="money positive">${fmt(t.income)}</strong></div><div class="report-stat"><p>Chi tiêu trong tháng</p><strong class="money">${fmt(t.expense)}</strong></div></div><div class="dashboard-grid"><section class="card"><div class="between section-heading">${monthPicker(true)}<div class="tabs"><button data-action="report-type" data-value="expense" class="${reportType==='expense'?'active':''}" style="min-height:34px">Chi</button><button data-action="report-type" data-value="income" class="${reportType==='income'?'active':''}" style="min-height:34px">Thu</button></div></div>${groups.length?`<div class="ring-layout"><div class="donut" style="background:conic-gradient(${gradient})" role="img" aria-label="Cơ cấu ${labelType(reportType)}: ${groups.map(g=>e(cat(g.category).name)+' '+fmt(g.amount)).join(', ')}"><div><span>Tổng ${reportType==='expense'?'chi':'thu'}</span><strong>${short(total)}</strong><span>${groups.length} danh mục</span></div></div><div class="chart-legend">${groups.slice(0,4).map(g=>`<span><span class="dot" style="background:${cat(g.category).color}"></span>${e(cat(g.category).name)}<b style="display:block;margin:5px 0 0 16px;font-weight:500">${Math.round(g.amount/total*100)}%</b></span>`).join('')}${groups.length>4?`<span class="muted">+ ${groups.length-4} danh mục khác</span>`:''}</div></div><p class="hint" style="margin-bottom:8px">Chạm vào danh mục để xem từng khoản.</p>${groups.map(g=>`<button class="category-report" data-action="report-drill" data-id="${g.category}"><div class="row"><span class="category-icon">${cat(g.category).emoji}</span><span class="grow small">${e(cat(g.category).name)}</span><span class="small money">${fmt(g.amount)}</span>${icon('chevron')}</div><div class="progress"><span style="background:${cat(g.category).color};width:${g.amount/total*100}%"></span></div></button>`).join('')}`:empty('Chưa có dữ liệu tháng này','Ghi một khoản để xem báo cáo của bạn.')}</section><div class="stack" style="align-content:start"><section class="card"><h2>Dòng tiền 6 tháng</h2><div class="chart-bar" role="img" aria-label="${six.map(v=>'Tháng '+Number(v.month.slice(5))+': thu '+fmt(v.income)+', chi '+fmt(v.expense)).join('; ')}">${six.map(v=>`<div class="bar-pair"><span style="height:${v.income/max*100}%" title="Thu ${fmt(v.income)}"></span><span style="height:${v.expense/max*100}%" title="Chi ${fmt(v.expense)}"></span><label>T${Number(v.month.slice(5))}</label></div>`).join('')}</div><div class="row small muted" style="justify-content:center;margin-top:16px"><span><i class="dot" style="background:#78a58c"></i>Thu nhập</span><span><i class="dot" style="background:#d9b779"></i>Chi tiêu</span></div></section><section class="card" style="background:#eff3e6"><div class="row">${icon('spark')}<h2>Nhìn lại tháng này</h2></div><p class="small" style="line-height:1.9;margin-top:13px">${t.income||t.expense?`Thu trừ chi ${t.net>=0?'còn':'âm'} <strong>${fmt(Math.abs(t.net))}</strong>. ${breakdown(state,month)[0]?`Khoản chi lớn nhất thuộc <strong>${e(cat(breakdown(state,month)[0].category).name)}</strong>.`:''}`:'Chưa đủ giao dịch để đưa ra nhận xét.'}</p><p class="hint" style="margin-top:10px">Tính từ dữ liệu mẫu, không dùng AI.</p></section><button class="btn wide" data-action="export">${icon('download')} Xuất giao dịch tháng này</button></div></div>`;}

const destinationLabel=value=>value==='company'?'Công ty':'Cá nhân';
function destinationPicker(value,disabled=false){
 return `<div class="send-destination"><span class="destination-caption">Gửi thu chi vào</span><div class="destination-switch" role="group" aria-label="Gửi thu chi vào" data-selected="${value}">${[['personal','wallet','Cá nhân'],['company','company','Công ty']].map(([key,symbol,label])=>`<button type="button" data-action="send-destination" data-value="${key}" aria-pressed="${key===value}" ${disabled?'disabled':''}>${icon(symbol)}${label}</button>`).join('')}</div></div>`;
}
// Prototype only: company entries stay local and never affect the personal wallet.
function addLocalEntries(rows,destination){
 if(destination==='company'){state.companyTransactions??=[];state.companyTransactions.unshift(...rows);}
 else state.transactions.unshift(...rows);
}
function quickLauncher(){
 return `<div class="quick-input"><button class="quick-prompt" data-action="entry">Hôm nay bạn chi gì?</button><div class="quick-actions" role="group" aria-label="Công cụ nhập nhanh"><button class="icon-btn" data-action="home-photo" data-source="receipt-file" aria-label="Ảnh kèm nội dung" title="Ảnh kèm nội dung">${icon('paperclip')}</button><button class="icon-btn" data-action="home-photo" data-source="camera-file" aria-label="Chụp bill" title="Chụp bill">${icon('camera')}</button><button class="icon-btn" data-action="home-photo" data-source="gallery-file" aria-label="Chọn ảnh" title="Chọn ảnh">${icon('imagePlus')}</button><button class="icon-btn" data-action="home-voice" aria-label="Ghi âm" title="Ghi âm (mô phỏng)">${icon('mic')}</button></div></div>${destinationPicker(sendDestination)}`;
}
function defaultTxn(type='expense'){return {id:id(),type,amount:'',category:state.categories.find(c=>c.id===(type==='income'?'salary':'food')&&!c.hidden)?.id??state.categories.find(c=>c.type===type&&!c.hidden)?.id,date:TODAY,wallet:'bank',toWallet:'cash',note:''};}
function openEntry(mode='quick',txn=null){entry={mode,destination:txn?'personal':sendDestination,draftDestination:null,text:'',image:null,imageName:'',voice:false,drafts:[],txn:txn?{...txn}:defaultTxn(),editing:!!txn};showEntry();}
function walletOptions(selected,exclude){return state.wallets.filter(w=>w.id!==exclude).map(w=>`<option value="${w.id}" ${selected===w.id?'selected':''}>${w.emoji} ${e(w.name)}</option>`).join('');}
function saveEntryFields(){const form=sheet.querySelector('#txn-form');if(form&&entry){const f=new FormData(form);entry.txn={...entry.txn,amount:f.get('amount'),note:f.get('note'),date:f.get('date'),wallet:f.get('wallet'),toWallet:f.get('toWallet')||entry.txn.toWallet};}}
function showEntry(){if(!entry)return;const t=entry.txn;const tabs=!entry.editing&&t.type!=='transfer'?`<div class="tabs"><button data-action="entry-mode" data-value="quick" class="${entry.mode==='quick'?'active':''}">Ghi nhanh</button><button data-action="entry-mode" data-value="manual" class="${entry.mode==='manual'?'active':''}">Nhập tay</button></div>`:'';
 if(entry.mode==='quick'){
 modal('Ghi thu chi',`${tabs}<p class="hint" style="margin-top:15px">Nhập nội dung, thêm ảnh hoặc ghi âm.</p><div class="quick-composer">${entry.image?`<div class="attachment"><img src="${entry.image}" alt="Ảnh bạn chọn"><div class="grow"><p>${e(entry.imageName)}</p><p class="muted">Thêm nội dung rồi gửi cùng ảnh</p></div><button class="icon-btn" data-action="remove-image" aria-label="Bỏ ảnh">${icon('x')}</button></div>`:''}${entry.voice?'<div class="voice-line">🎙️ Đang thử giọng nói mẫu…<br>Bấm dừng để tự gửi “Cà phê 55k”.</div>':''}<textarea id="quick-text" aria-label="Nội dung thu chi" placeholder="Ví dụ: Cà phê 55k; đi chợ 420k">${e(entry.text)}</textarea><div class="quick-tools"><button class="icon-btn" data-action="pick-image" aria-label="Thêm ảnh kèm nội dung" title="Ảnh kèm nội dung">${icon('paperclip')}</button><button class="icon-btn" data-action="camera" aria-label="Chụp ảnh hóa đơn">${icon('camera')}</button><button class="icon-btn" data-action="gallery" aria-label="Chọn ảnh" title="Chọn ảnh">${icon('imagePlus')}</button><button class="icon-btn ${entry.voice?'recording':''}" data-action="voice" aria-label="${entry.voice?'Dừng và tự gửi giọng nói mẫu':'Thử giọng nói mẫu'}">${icon(entry.voice?'stop':'mic')}</button><button class="btn primary" data-action="parse-quick">${icon('send')} Gửi</button></div><input type="file" id="receipt-file" accept="image/*" hidden><input type="file" id="camera-file" accept="image/*" capture="environment" hidden><input type="file" id="gallery-file" accept="image/*" hidden></div>${destinationPicker(entry.destination,entry.voice)}<div id="entry-error" class="form-error" role="alert"></div>${entry.drafts.length?`<div class="between" style="margin-top:19px"><h3>Xem lại trước khi lưu</h3><span class="pill">${entry.drafts.length} khoản</span></div>${entry.drafts.map((d,i)=>`<div class="draft"><div class="between"><span class="draft-label">${destinationLabel(entry.draftDestination)} · ${labelType(d.type)}</span><button class="icon-btn" data-action="edit-draft" data-index="${i}" aria-label="Sửa khoản ${i+1}">${icon('edit')}</button></div><p>${e(d.note)}</p><div class="between"><span class="draft-money money">${fmt(d.amount)}</span><span class="hint">${dateLabel(d.date)}</span></div><button class="select-category" data-action="draft-category" data-index="${i}"><span>${cat(d.category).emoji} ${e(cat(d.category).name)}</span>${icon('down')}</button><p class="hint">${entry.draftDestination==='company'?'Sổ thu chi công ty':e(wallet(d.wallet).name)}</p></div>`).join('')}<p class="review-note">${entry.draftDestination==='company'?'Các khoản này được ghi vào sổ công ty.':'Chỉ khi bấm Lưu, số dư, lịch sử và báo cáo mới thay đổi.'}</p>`:''}`,entry.drafts.length?button('save-drafts',icon('check')+` Lưu ${entry.drafts.length} khoản${entry.draftDestination==='company'?' công ty':''}`,'primary wide'):'');
 }else{
 const transfer=t.type==='transfer';
 modal(entry.editing?'Chi tiết giao dịch':transfer?'Chuyển tiền giữa ví':'Ghi thu chi',`${tabs}${!transfer?`<div class="tabs" style="margin-top:16px"><button data-action="txn-type" data-value="expense" class="${t.type==='expense'?'active':''}">− Chi tiêu</button><button data-action="txn-type" data-value="income" class="${t.type==='income'?'active':''}">+ Thu nhập</button></div>`:'<p class="hint">Tiền chuyển giữa ví của bạn không làm tăng thu hoặc chi.</p>'}<form id="txn-form" data-form="txn" class="form-grid" style="margin-top:19px" novalidate><label class="field"><span>Số tiền</span><div class="amount-input"><input name="amount" inputmode="decimal" aria-label="Số tiền" placeholder="0" value="${e(t.amount)}" autocomplete="off"><span>₫</span></div></label>${transfer?'':`<div class="field"><span>Danh mục</span><button class="select-category" type="button" data-action="txn-category"><span>${cat(t.category).emoji} ${e(cat(t.category).name)}</span>${icon('down')}</button></div>`}<div class="two-cols"><label class="field"><span>${transfer?'Từ ví':'Ví thanh toán'}</span><select name="wallet" aria-label="${transfer?'Ví chuyển':'Ví thanh toán'}">${walletOptions(t.wallet)}</select></label><label class="field"><span>${transfer?'Đến ví':'Ngày giao dịch'}</span>${transfer?`<select name="toWallet" aria-label="Ví nhận">${walletOptions(t.toWallet)}</select>`:`<input type="date" name="date" aria-label="Ngày giao dịch" value="${t.date}">`}</label></div>${transfer?`<label class="field"><span>Ngày chuyển</span><input type="date" name="date" value="${t.date}" aria-label="Ngày chuyển"></label>`:''}<label class="field"><span>Ghi chú</span><input name="note" aria-label="Ghi chú" maxlength="160" placeholder="Khoản này dành cho điều gì?" value="${e(t.note)}"></label><div id="entry-error" class="form-error" role="alert"></div></form>${!transfer&&!entry.editing&&entry.draftIndex===undefined?destinationPicker(entry.destination):''}`, `<div class="row">${entry.editing?button('delete-txn',icon('trash'),'danger','aria-label="Xóa giao dịch"'):''}<button class="btn primary grow" type="submit" form="txn-form">${icon('check')} ${entry.draftIndex!==undefined?'Cập nhật bản nháp':entry.editing?'Lưu thay đổi':transfer?'Chuyển tiền':entry.destination==='company'?'Lưu khoản công ty':'Lưu giao dịch'}</button></div>`);
 }
}
function showCategories(context=categoryContext){
 categoryContext=context;const type=context?.type||categoryType,selected=context?.selected;
 modal(context?'Chọn danh mục':'Quản lý danh mục',`${context?'':`<div class="tabs"><button data-action="category-type" data-value="expense" class="${type==='expense'?'active':''}">Chi tiêu</button><button data-action="category-type" data-value="income" class="${type==='income'?'active':''}">Thu nhập</button></div>`}<p class="hint" style="margin-top:13px">${type==='expense'?'Danh mục chi tiêu':'Danh mục thu nhập'} · ${context?'Chạm để chọn':'Chạm để sửa tên, biểu tượng hoặc ẩn'}</p><div class="category-grid">${state.categories.filter(c=>c.type===type&&(!context||!c.hidden||selected===c.id)).map(c=>`<button class="category-cell ${selected===c.id?'selected':''} ${c.hidden?'category-hidden':''}" data-action="${context?'choose-category':'edit-category'}" data-id="${e(c.id)}" ${context?'':`aria-label="Sửa danh mục ${e(c.name)}"`}><span class="category-icon">${e(c.emoji)}</span><span>${e(c.name)}</span>${c.hidden?'<small>Đang ẩn</small>':''}</button>`).join('')}</div>`,button('new-category',icon('plus')+' Thêm danh mục','soft wide'));
}
function categoryRemovalReason(c){
 if([...state.transactions,...(state.companyTransactions??[]),...(entry?.drafts??[])].some(t=>t.category===c.id)||state.budgets.some(b=>b.category===c.id))return 'Danh mục đang có giao dịch hoặc ngân sách. Bạn có thể ẩn để giữ lịch sử.';
 if(!c.custom)return 'Danh mục gợi ý mặc định được giữ cho ghi nhanh. Bạn có thể ẩn nếu không sử dụng.';
 return '';
}
function newCategory(){editingCategoryId=null;newEmoji='🏷️';showNewCategory();}
function showNewCategory(){
 const current=state.categories.find(c=>c.id===editingCategoryId),type=current?.type||categoryContext?.type||categoryType,reason=current?categoryRemovalReason(current):'';
 const emojis=[...new Set([...(current?[current.emoji]:[]),'🏷️','🍜','☕','🏠','🐾','🎁','🌱','💼','🧘','👨‍👩‍👧','🚗','💻'])];
 modal(current?'Sửa danh mục':'Thêm danh mục',`<form id="category-form" data-form="category" data-id="${e(current?.id||'')}" class="form-grid"><p class="hint">Danh mục ${type==='expense'?'chi':'thu'} dùng chung trong ví và ghi nhanh.</p><label class="field"><span>Tên danh mục</span><input type="text" name="name" aria-label="Tên danh mục" maxlength="40" placeholder="Ví dụ: Chăm sóc ba mẹ" value="${e(current?.name||'')}" required autocomplete="off"></label><div class="field"><span>Chọn biểu tượng</span><div class="emoji-options">${emojis.map(x=>`<button type="button" data-action="emoji" data-value="${x}" class="${x===newEmoji?'selected':''}" aria-label="Biểu tượng ${x}">${x}</button>`).join('')}</div></div>${current?`<label class="wallet-visible"><input type="checkbox" name="visible" ${!current.hidden?'checked':''}><span>Hiển thị khi chọn danh mục<small>Ẩn vẫn giữ giao dịch và ngân sách đã có.</small></span></label>`:''}<div id="category-error" class="form-error" role="alert"></div></form>${current?`<div class="wallet-delete">${button('delete-category',icon('trash')+' Xóa danh mục','danger wide',`data-id="${e(current.id)}" ${reason?'disabled aria-describedby="category-delete-reason"':''}`)}${reason?`<p class="hint" id="category-delete-reason">${reason}</p>`:''}</div>`:''}`,`<div class="row">${button('back-categories','Quay lại','')}<button class="btn primary grow" form="category-form">${icon(current?'check':'plus')} ${current?'Lưu danh mục':'Tạo danh mục'}</button></div>`);
}
function deleteCategory(c){
 const reason=categoryRemovalReason(c);if(reason){toast(reason);return;}
 modal('Xóa danh mục này?',`<p class="small">Xóa <strong>${e(c.name)}</strong>? Danh mục này chưa có giao dịch hoặc ngân sách.</p>`,`<div class="row">${button('edit-category','Giữ lại','grow',`data-id="${e(c.id)}"`)}${button('confirm-delete-category','Xóa danh mục','danger grow',`data-id="${e(c.id)}"`)}</div>`);
}
function settings(){modal('Góc cá nhân',`<p class="hint" style="margin-bottom:13px">Bản demo tương tác · Số liệu giả lập tháng 10/2026.</p>${[['categories','tag','Danh mục thu chi','Thêm danh mục theo cách của bạn'],['wallets','wallet','Ví & tài khoản','Tiền mặt, ngân hàng, tiết kiệm'],['transfer','transfer','Chuyển tiền giữa ví','Không tính vào thu hoặc chi'],['reset','reset','Đặt lại dữ liệu mẫu','Chỉ xóa các thao tác thử trong demo']].map(([action,i,title,sub])=>`<button class="list-item" data-action="${action}"><span class="category-icon">${icon(i)}</span><span class="grow"><h3>${title}</h3><p class="hint">${sub}</p></span>${icon('chevron')}</button>`).join('')}<a class="btn wide" href="./flow.html" style="margin-top:20px">${icon('plan')} Xem báo cáo & sơ đồ luồng ${icon('arrow')}</a><p class="hint" style="margin-top:15px">Đây là bản đề xuất. Chưa đồng bộ tài khoản, ngân hàng hoặc sổ sách thật.</p>`);}
const walletTypes={bank:'Tài khoản ngân hàng',cash:'Tiền mặt',ewallet:'Ví điện tử',saving:'Tiết kiệm',other:'Khác'};
const walletEmojis=['🏦','👛','🌱','📱','💳','💵','🪙','🎯'];
const walletKind=w=>w.kind??({bank:'bank',cash:'cash',saving:'saving'}[w.id]||'other');
function walletRemovalReason(w){
 if([...state.transactions,...(state.companyTransactions??[])].some(t=>t.wallet===w.id||t.toWallet===w.id))return 'Ví đã có giao dịch. Bạn có thể ẩn khỏi Tổng quan để giữ lịch sử.';
 if(w.id==='saving'&&state.goals.length)return 'Ví đang dùng cho mục tiêu tiết kiệm. Bạn có thể sửa tên hoặc ẩn khỏi Tổng quan.';
 if(['bank','cash','saving'].includes(w.id))return 'Ví mặc định đang được dùng trong luồng ghi thu chi. Bạn có thể sửa tên hoặc ẩn khỏi Tổng quan.';
 return '';
}
function wallets(){
 modal('Quản lý ví',`<p class="hint" style="margin-bottom:12px">Thêm ví, chỉnh thông tin hoặc chọn ví để xem giao dịch.</p><div class="wallet-settings-list">${state.wallets.map(w=>`<div class="wallet-settings-row"><button class="wallet-detail" data-action="filter-wallet" data-id="${e(w.id)}"><span class="category-icon">${e(w.emoji)}</span><span class="grow"><strong>${e(w.name)}</strong><span class="hint">${walletTypes[walletKind(w)]||'Khác'}${w.hidden?' · Đang ẩn':''}</span><b class="money">${fmt(balance(state,w.id))}</b></span></button><button class="icon-btn" data-action="edit-wallet" data-id="${e(w.id)}" aria-label="Sửa ví ${e(w.name)}">${icon('edit')}</button></div>`).join('')}</div><p class="hint" style="margin-top:14px">Tổng số dư <strong>${fmt(sumBalance())}</strong></p>`,button('new-wallet',icon('plus')+' Thêm ví','primary wide'));
}
function newWallet(w=null){
 const reason=w?walletRemovalReason(w):'',selectedEmoji=w?.emoji??'👛';
 modal(w?'Cấu hình ví':'Thêm ví',`<form id="wallet-form" data-form="wallet" data-id="${e(w?.id||'')}" class="form-grid" novalidate>${w?`<div class="wallet-current"><span>Số dư hiện tại</span><strong class="money">${fmt(balance(state,w.id))}</strong></div>`:''}<label class="field"><span>Tên ví</span><input type="text" name="name" aria-label="Tên ví" maxlength="35" required placeholder="Ví dụ: MoMo" value="${e(w?.name||'')}"></label><label class="field"><span>Loại ví</span><select name="kind" aria-label="Loại ví">${Object.entries(walletTypes).map(([key,label])=>`<option value="${key}" ${key===(w?walletKind(w):'ewallet')?'selected':''}>${label}</option>`).join('')}</select></label><fieldset class="wallet-icon-picker"><legend>Biểu tượng</legend>${walletEmojis.map(emoji=>`<label><input type="radio" name="emoji" value="${emoji}" aria-label="Biểu tượng ${emoji}" ${emoji===selectedEmoji?'checked':''}><span>${emoji}</span></label>`).join('')}</fieldset><label class="field"><span>Số dư ban đầu</span><input type="text" name="opening" aria-label="Số dư ban đầu" inputmode="decimal" value="${w?.opening??0}"></label><p class="hint">Số dư ban đầu cộng với các khoản đã ghi để ra số dư hiện tại; không tính vào thu nhập tháng.</p><label class="wallet-visible"><input type="checkbox" name="visible" ${!w?.hidden?'checked':''}><span>Hiển thị trên Tổng quan<small>Ẩn ví vẫn giữ số dư, lịch sử và báo cáo.</small></span></label><div id="wallet-error" class="form-error" role="alert"></div></form>${w?`<div class="wallet-delete">${button('delete-wallet',icon('trash')+' Xóa ví','danger wide',`data-id="${e(w.id)}" ${reason?'disabled aria-describedby="wallet-delete-reason"':''}`)}${reason?`<p class="hint" id="wallet-delete-reason">${reason}</p>`:''}</div>`:''}`,`<div class="row">${button('wallets','Quay lại','')}<button class="btn primary grow" form="wallet-form">${w?'Lưu thay đổi':'Tạo ví'}</button></div>`);
}
function deleteWallet(w){
 const reason=walletRemovalReason(w);if(reason){toast(reason);return;}
 modal('Xóa ví này?',`<p class="small">Xóa <strong>${e(w.name)}</strong>? Ví chưa có giao dịch. Số dư ${fmt(w.opening)} của ví sẽ được bỏ khỏi tổng số dư.</p>`,`<div class="row">${button('edit-wallet','Giữ lại','grow',`data-id="${e(w.id)}"`)}${button('confirm-delete-wallet','Xóa ví','danger grow',`data-id="${e(w.id)}"`)}</div>`);
}
function budgetForm(b=null){modal(b?.id?'Sửa ngân sách':'Thêm ngân sách',`<form id="budget-form" data-form="budget" data-id="${b?.id||''}" class="form-grid"><label class="field"><span>Danh mục chi tiêu</span><select name="category" aria-label="Danh mục ngân sách">${state.categories.filter(c=>c.type==='expense'&&(!c.hidden||c.id===b?.category)).map(c=>`<option value="${c.id}" ${c.id===b?.category?'selected':''}>${c.emoji} ${e(c.name)}</option>`).join('')}</select></label>${button('budget-new-category',icon('plus')+' Thêm danh mục','soft','type="button"')}<label class="field"><span>Giới hạn mỗi tháng</span><input type="text" name="amount" inputmode="decimal" aria-label="Giới hạn mỗi tháng" value="${b?.amount||''}" placeholder="Ví dụ: 3tr" required></label><p class="hint">Tính tất cả khoản chi của danh mục trong tháng, trên mọi ví cá nhân. Hạn mức này lặp lại hằng tháng.</p><div id="budget-error" class="form-error" role="alert"></div></form>`,`<button class="btn primary wide" form="budget-form">Lưu ngân sách</button>`);}
function amountModal(title,formName,label,extra='',formId='amount-form'){modal(title,`<form id="${formId}" data-form="${formName}" class="form-grid">${extra}<label class="field"><span>${label}</span><input type="text" name="amount" inputmode="decimal" aria-label="${label}" placeholder="Ví dụ: 1tr" required></label><div id="amount-error" class="form-error" role="alert"></div></form>`,`<button class="btn primary wide" form="${formId}">Lưu</button>`);}
function parse(){entry.text=sheet.querySelector('#quick-text')?.value??entry.text;let text=entry.text.trim();if(entry.image&&!text){sheet.querySelector('#entry-error').textContent='Thêm nội dung và số tiền cho ảnh trước khi gửi.';return;}const parsed=parseQuick(text,state);if(parsed.error){sheet.querySelector('#entry-error').textContent=parsed.error;return;}entry.drafts=parsed.rows;entry.draftDestination=entry.destination;showEntry();sheet.querySelector('.draft')?.scrollIntoView({block:'nearest',behavior:'smooth'});}
function confirmDialog(title,message,action){modal(title,`<p class="small" style="line-height:1.9">${message}</p>`,`<div class="row">${button('close','Hủy','grow')}${button(action,'Xác nhận','danger grow')}</div>`);}
function errorAt(id,message){const node=document.getElementById(id);if(node){node.textContent=message;node.scrollIntoView({block:'nearest'});}}

document.addEventListener('click',event=>{const node=event.target.closest('[data-action]');if(!node)return;const a=node.dataset.action,v=node.dataset.value,cid=node.dataset.id;
 if(a==='close'){close();return;}
 if(a==='nav'){close();screen=node.dataset.screen;render();window.scrollTo(0,0);}
 else if(a==='month-prev'||a==='month-next'){const d=new Date(`${month}-15T12:00:00Z`);d.setUTCMonth(d.getUTCMonth()+(a==='month-next'?1:-1));month=d.toISOString().slice(0,7);render();}
 else if(a==='hide-balance'){hideBalance=!hideBalance;render();}
 else if(a==='entry'){openEntry();}
 else if(a==='home-photo'){openEntry();sheet.querySelector('#'+node.dataset.source).click();}
 else if(a==='home-voice'){openEntry();entry.voice=true;showEntry();}
 else if(a==='send-destination'){
  if(!['personal','company'].includes(v)||entry?.voice)return;
  sendDestination=v;
  if(entry){entry.text=sheet.querySelector('#quick-text')?.value??entry.text;saveEntryFields();entry.destination=v;showEntry();}
  render();
 }
 else if(a==='entry-mode'){saveEntryFields();entry.mode=v;showEntry();}
 else if(a==='txn-type'){saveEntryFields();entry.txn.type=v;entry.txn.category=defaultTxn(v).category;showEntry();}
 else if(a==='edit-txn'){const txn=state.transactions.find(t=>t.id===cid);openEntry('manual',txn);}
 else if(a==='txn-category'){saveEntryFields();showCategories({type:entry.txn.type,selected:entry.txn.category,onSelect:value=>{entry.txn.category=value;showEntry();}});}
 else if(a==='draft-category'){const d=entry.drafts[Number(node.dataset.index)];showCategories({type:d.type,selected:d.category,onSelect:value=>{d.category=value;showEntry();}});}
 else if(a==='edit-draft'){entry.draftIndex=Number(node.dataset.index);entry.txn={...entry.drafts[entry.draftIndex]};entry.mode='manual';showEntry();}
 else if(a==='parse-quick'){parse();}
 else if(a==='voice'){entry.text=sheet.querySelector('#quick-text').value;if(entry.voice){entry.voice=false;entry.text=[entry.text.trim(),'Cà phê 55k'].filter(Boolean).join('; ');showEntry();parse();}else{entry.voice=true;showEntry();}}
 else if(a==='pick-image'||a==='camera'||a==='gallery'){sheet.querySelector(a==='camera'?'#camera-file':a==='gallery'?'#gallery-file':'#receipt-file').click();}
 else if(a==='remove-image'){URL.revokeObjectURL(entry.image);entry.image=null;showEntry();}
 else if(a==='save-drafts'){if(!entry?.drafts.length)return;const failure=entry.drafts.map(t=>validateTxn(t,state)).find(Boolean);if(failure){errorAt('entry-error',failure);return;}const count=entry.drafts.length,destination=entry.draftDestination;addLocalEntries(entry.drafts,destination);close();commit(`Đã lưu ${count} khoản ${destination==='company'?'công ty':'cá nhân'}`);}
 else if(a==='categories'){categoryType='expense';showCategories(null);}
 else if(a==='category-type'){categoryType=v;showCategories(null);}
 else if(a==='choose-category'){if(categoryContext?.onSelect){categoryContext.onSelect(cid);}else{close();filters={type:cat(cid).type,wallet:'all',category:cid,search:''};screen='transactions';render();}}
 else if(a==='new-category'){newCategory();}
 else if(a==='edit-category'){const c=state.categories.find(c=>c.id===cid);if(!c)return;editingCategoryId=c.id;categoryType=c.type;newEmoji=c.emoji;showNewCategory();}
 else if(a==='delete-category'){const c=state.categories.find(c=>c.id===cid);if(c)deleteCategory(c);}
 else if(a==='confirm-delete-category'){
  const c=state.categories.find(c=>c.id===cid);if(!c)return;const reason=categoryRemovalReason(c);if(reason){toast(reason);return;}
  state.categories=state.categories.filter(c=>c.id!==cid);if(filters.category===cid)filters.category='all';editingCategoryId=null;commit('Đã xóa danh mục');showCategories(null);
 }
 else if(a==='budget-new-category'){
  const form=sheet.querySelector('#budget-form'),f=new FormData(form),draft={id:form.dataset.id,category:f.get('category'),amount:f.get('amount')};
  categoryContext={type:'expense',selected:draft.category,onSelect:value=>budgetForm({...draft,category:value})};newCategory();
 }
 else if(a==='back-categories'){showCategories();}
 else if(a==='emoji'){newEmoji=v;sheet.querySelectorAll('[data-action=emoji]').forEach(el=>el.classList.toggle('selected',el===node));}
 else if(a==='settings'){settings();}
 else if(a==='wallets'){wallets();}
 else if(a==='new-wallet'){newWallet();}
 else if(a==='edit-wallet'){const w=state.wallets.find(w=>w.id===cid);if(w)newWallet(w);}
 else if(a==='delete-wallet'){const w=state.wallets.find(w=>w.id===cid);if(w)deleteWallet(w);}
 else if(a==='confirm-delete-wallet'){
  const w=state.wallets.find(w=>w.id===cid);if(!w)return;const reason=walletRemovalReason(w);if(reason){toast(reason);newWallet(w);return;}
  state.wallets=state.wallets.filter(w=>w.id!==cid);if(filters.wallet===cid)filters.wallet='all';commit('Đã xóa ví '+w.name);wallets();
 }
 else if(a==='filter-wallet'){close();filters={type:'all',wallet:cid,category:'all',search:''};screen='transactions';render();}
 else if(a==='filter-type'){filters.type=v;filters.category='all';render();}
 else if(a==='transaction-filters'){modal('Lọc theo ví',`<div class="stack">${button('choose-wallet-filter','Tất cả các ví','soft wide','data-id="all"')}${state.wallets.map(w=>button('choose-wallet-filter',w.emoji+' '+e(w.name),'wide',`data-id="${w.id}"`)).join('')}</div>`,`<div class="row">${button('new-wallet',icon('plus')+' Thêm ví','primary grow')}${button('wallets',icon('settings')+' Quản lý ví','grow')}</div>`);}
 else if(a==='choose-wallet-filter'){filters.wallet=cid;close();render();}
 else if(a==='clear-category'){filters.category='all';render();}
 else if(a==='clear-filters'){filters={type:'all',wallet:'all',category:'all',search:''};render();}
 else if(a==='report-drill'){filters={type:reportType,wallet:'all',category:cid,search:''};screen='transactions';render();window.scrollTo(0,0);}
 else if(a==='report-type'){reportType=v;render();}
 else if(a==='plan-tab'){planTab=v;render();}
 else if(a==='new-budget'){budgetForm();}
 else if(a==='edit-budget'){budgetForm(state.budgets.find(b=>b.id===cid));}
 else if(a==='monthly-budget'){amountModal('Ngân sách mỗi tháng','monthly','Ngân sách tháng');sheet.querySelector('[name=amount]').value=state.monthlyLimit;}
 else if(a==='transfer'){openEntry('manual');entry.destination='personal';entry.txn.type='transfer';entry.txn.note='Chuyển giữa các ví';showEntry();}
 else if(a==='new-goal'){amountModal('Mục tiêu mới','goal','Số tiền mục tiêu','<label class="field"><span>Tên mục tiêu</span><input name="name" aria-label="Tên mục tiêu" maxlength="40" required placeholder="Ví dụ: Du lịch Đà Lạt"></label>');}
 else if(a==='contribute'){const g=state.goals.find(g=>g.id===cid);amountModal('Bỏ thêm vào '+e(g.name),'contribute','Số tiền tiết kiệm',`<input type="hidden" name="goal" value="${g.id}"><label class="field"><span>Chuyển từ ví</span><select name="wallet" aria-label="Chuyển từ ví">${walletOptions('bank','saving')}</select></label><p class="hint">Tiền sẽ chuyển vào Ví tiết kiệm và được cộng vào mục tiêu.</p>`);}
 else if(a==='delete-txn'){if(entry.txn.goalId){toast('Khoản góp quỹ được giữ để bảo toàn tiến độ mục tiêu trong demo.');return;}confirmDialog('Xóa giao dịch này?','Số dư, ngân sách và báo cáo sẽ được tính lại.', 'confirm-delete');}
 else if(a==='confirm-delete'){state.transactions=state.transactions.filter(t=>t.id!==entry.txn.id);close();commit('Đã xóa giao dịch demo');}
 else if(a==='reset'){confirmDialog('Đặt lại bản demo?','Các khoản, danh mục và kế hoạch bạn vừa thử sẽ được thay bằng dữ liệu mẫu ban đầu.','confirm-reset');}
 else if(a==='confirm-reset'){close();state=seed();month='2026-10';filters={type:'all',wallet:'all',category:'all',search:''};screen='home';commit('Đã khôi phục dữ liệu mẫu');}
 else if(a==='export'){const cell=s=>'"'+String(s??'').replace(/^[=+\-@]/,"'").replaceAll('"','""')+'"';const data=[['Ngày','Loại','Số tiền','Danh mục','Ghi chú','Ví','Ví nhận'],...monthRows(state,month).map(t=>[t.date,labelType(t.type),t.amount,t.type==='transfer'?'':cat(t.category).name,t.note,wallet(t.wallet).name,t.toWallet?wallet(t.toWallet).name:''])].map(r=>r.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+data],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`vi-ca-nhan-demo-${month}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Đã xuất giao dịch mẫu của tháng');}
});
document.addEventListener('input',event=>{if(event.target.id==='quick-text')entry.text=event.target.value;if(event.target.id==='txn-search'){filters.search=event.target.value;document.getElementById('txn-list').innerHTML=transactionList();}});
document.addEventListener('change',event=>{if(['receipt-file','camera-file','gallery-file'].includes(event.target.id)){const file=event.target.files?.[0];if(!file)return;if(!file.type.startsWith('image/')){toast('Chọn một tệp ảnh.');return;}if(file.size>10*1024*1024){toast('Chọn ảnh dưới 10 MB cho demo.');return;}if(entry.image)URL.revokeObjectURL(entry.image);entry.image=URL.createObjectURL(file);entry.imageName=file.name;showEntry();}});
document.addEventListener('submit',event=>{const form=event.target;if(!form.dataset.form)return;event.preventDefault();const f=new FormData(form),type=form.dataset.form;
 if(type==='txn'){
  saveEntryFields();const t={...entry.txn,amount:money(f.get('amount')),note:String(f.get('note')).trim()};const failure=validateTxn(t,state);if(failure){errorAt('entry-error',failure);return;}
  if(entry.draftIndex!==undefined){entry.drafts[entry.draftIndex]=t;delete entry.draftIndex;entry.mode='quick';showEntry();return;}
  if(entry.editing){const old=state.transactions.find(x=>x.id===t.id);if(old.goalId){errorAt('entry-error','Khoản góp quỹ được giữ nguyên trong demo. Bạn có thể tạo khoản chuyển mới.');return;}state.transactions=state.transactions.map(x=>x.id===t.id?t:x);}else addLocalEntries([t],entry.destination);
  const destination=entry.destination;close();commit(`Đã lưu giao dịch ${destinationLabel(destination).toLocaleLowerCase('vi')}`);
 }else if(type==='category'){
  const categoryId=form.dataset.id,old=state.categories.find(c=>c.id===categoryId),name=String(f.get('name')).trim().replace(/\s+/g,' '),kind=old?.type||categoryContext?.type||categoryType,hidden=old?!f.has('visible'):false;
  if(categoryId&&!old){errorAt('category-error','Danh mục không còn tồn tại. Mở lại danh sách.');return;}
  if(!name||name.length>40){errorAt('category-error','Nhập tên danh mục, tối đa 40 ký tự.');return;}
  if(state.categories.some(c=>c.id!==categoryId&&c.type===kind&&c.name.toLocaleLowerCase('vi')===name.toLocaleLowerCase('vi'))){errorAt('category-error','Danh mục này đã có. Hãy chọn tên khác.');return;}
  if(hidden&&!state.categories.some(c=>c.id!==categoryId&&c.type===kind&&!c.hidden)){errorAt('category-error','Giữ ít nhất một danh mục hiển thị cho mỗi loại thu/chi.');return;}
  const c={...old,id:categoryId||id(),name,emoji:newEmoji,type:kind,color:old?.color||'#95ad93',custom:old?old.custom:true,hidden};
  if(old)state.categories=state.categories.map(item=>item.id===categoryId?c:item);else state.categories.push(c);
  editingCategoryId=null;commit(old?'Đã cập nhật danh mục':'Đã tạo danh mục '+name);if(categoryContext?.onSelect){categoryContext.onSelect(c.id);}else showCategories();
 }else if(type==='wallet'){
  const walletId=form.dataset.id,old=state.wallets.find(w=>w.id===walletId),name=String(f.get('name')).trim().replace(/\s+/g,' '),opening=money(f.get('opening')),kind=String(f.get('kind')),emoji=String(f.get('emoji'));
  if(walletId&&!old){errorAt('wallet-error','Ví này không còn tồn tại. Mở lại danh sách ví.');return;}
  if(!name||name.length>35||!Number.isSafeInteger(opening)||opening<0||opening>1e12){errorAt('wallet-error','Nhập tên và số dư từ 0 đến 1.000 tỷ đồng.');return;}
  if(!Object.hasOwn(walletTypes,kind)||!walletEmojis.includes(emoji)){errorAt('wallet-error','Chọn loại và biểu tượng ví.');return;}
  if(state.wallets.some(w=>w.id!==walletId&&w.name.toLocaleLowerCase('vi')===name.toLocaleLowerCase('vi'))){errorAt('wallet-error','Tên ví này đã có.');return;}
  const updated={...old,id:walletId||id(),name,opening,kind,emoji,hidden:!f.has('visible')};
  if(old)state.wallets=state.wallets.map(w=>w.id===walletId?updated:w);else state.wallets.push(updated);
  commit(old?'Đã cập nhật ví':'Đã tạo ví mới');wallets();
 }else if(type==='budget'){
  const amount=money(f.get('amount')),category=f.get('category');if(!Number.isSafeInteger(amount)||amount<=0||amount>1e12){errorAt('budget-error','Nhập ngân sách hợp lệ lớn hơn 0.');return;}if(state.budgets.some(b=>b.category===category&&b.id!==form.dataset.id)){errorAt('budget-error','Danh mục này đã có ngân sách. Hãy sửa mức hiện tại.');return;}const b={id:form.dataset.id||id(),category,amount};state.budgets=state.budgets.filter(x=>x.id!==b.id).concat(b);close();commit('Đã lưu ngân sách');
 }else{
  const amount=money(f.get('amount'));if(!Number.isSafeInteger(amount)||amount<=0||amount>1e12){errorAt('amount-error','Nhập số tiền hợp lệ lớn hơn 0.');return;}
  if(type==='monthly')state.monthlyLimit=amount;
  if(type==='goal'){const name=String(f.get('name')).trim();if(!name){errorAt('amount-error','Nhập tên mục tiêu.');return;}state.goals.push({id:id(),name,target:amount,saved:0,emoji:'🎯'});}
  if(type==='contribute'){const g=state.goals.find(x=>x.id===f.get('goal'));state.transactions.unshift({id:id(),type:'transfer',amount,wallet:f.get('wallet'),toWallet:'saving',date:TODAY,note:'Góp quỹ: '+g.name,goalId:g.id});g.saved+=amount;}
  close();commit('Đã cập nhật kế hoạch');
 }
});
render();
